<script setup lang="ts">import{computed,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{listPublicArticles,type PublicArticleSummary}from'../../api/articles';import{getPublicColumn,getPublicColumnByAlias,type PublicColumn}from'../../api/columns';import PublicSiteHeader from'../../components/PublicSiteHeader.vue';import PublicSiteFooter from'../../components/PublicSiteFooter.vue';import{setPageMeta}from'../../seo';const route=useRoute(),router=useRouter();const column=ref<PublicColumn|null>(null),breadcrumbs=ref<PublicColumn[]>([]),articles=ref<PublicArticleSummary[]>([]),total=ref(0),page=ref(0),error=ref(''),loading=ref(false);const size=10,hasPrevious=computed(()=>page.value>0),hasNext=computed(()=>(page.value+1)*size<total.value);watch(()=>[route.params.alias,route.params.id,route.query.page],load,{immediate:true});async function load(){const alias=typeof route.params.alias==='string'?route.params.alias:null;const id=Number(route.params.id);const requested=Math.max(0,Number(route.query.page??0)||0);column.value=null;breadcrumbs.value=[];articles.value=[];error.value='';loading.value=true;try{const current=alias?await getPublicColumnByAlias(alias):await getPublicColumn(id);const trail=[current];const seen=new Set([current.id]);let parent=current.parentId;while(parent!=null&&!seen.has(parent)){const p=await getPublicColumn(parent);trail.unshift(p);seen.add(p.id);parent=p.parentId}const ap=await listPublicArticles(current.id,requested,size);column.value=current;breadcrumbs.value=trail;articles.value=ap.items;total.value=ap.total;page.value=ap.page;setPageMeta({title:current.name,description:`浏览“${current.name}”栏目已发布信息。`})}catch(e){error.value=e instanceof Error?e.message:'栏目加载失败'}finally{loading.value=false}}function go(p:number){void router.push({path:route.path,query:p>0?{page:String(p)}:{}})}</script><template><PublicSiteHeader/><main class="content-shell site-width"><nav class="breadcrumb"><router-link to="/">首页</router-link><template v-for="i in breadcrumbs" :key="i.id"><span>/</span><router-link :to="i.alias?`/column/${i.alias}`:`/columns/${i.id}`">{{i.name}}</router-link></template></nav><p v-if="loading" class="public-state">正在加载栏目…</p><template v-else-if="column"><header class="column-title"><h1>{{column.name}}</h1></header><div class="column-list" data-testid="column-articles"><article v-for="a in articles" :key="a.id"><router-link :data-testid="`column-article-${a.id}`" :to="`/article/${a.id}`">{{a.title}}</router-link><time v-if="a.publishDate">{{a.publishDate}}</time></article><p v-if="!articles.length" class="empty-item">当前栏目暂无已发布内容。</p></div><div v-if="total>size" class="pagination"><button :disabled="!hasPrevious" @click="go(page-1)">上一页</button><span>第 {{page+1}} 页</span><button :disabled="!hasNext" @click="go(page+1)">下一页</button></div></template><p v-else class="public-state error-text">{{error}}</p></main><PublicSiteFooter/></template>
